import { createRequire } from 'node:module';
import { Plugin } from "esbuild";
import { ChildProcess, fork } from 'node:child_process';

export type StopFn = () => Promise<void>;


export function startPlugin(mainFile: string): Plugin {
  const require = createRequire(import.meta.url);
  const serverRunnerPath = require.resolve('./server-runner.js');
  let serverProcess: ChildProcess|undefined;

  function forkProcess() {
    require.resolve('./server-runner.js');
    return fork(serverRunnerPath, [mainFile], {
      execArgv: ['--enable-source-maps']
    });
  }

  let isFirstBuild = true;

  return {
    name: "start-plugin",
    setup(build) {
      process.on('exit', () => {
        if (!serverProcess) return;
        serverProcess.kill('SIGKILL');
      });

      build.onStart(() => {
        if (!isFirstBuild) {
          process.stdout.write('\r\x1b[K\x1b[90m⟳ Compiling backend...\x1b[0m');
        }
      });

      build.onEnd(async (result) => {
        const first = isFirstBuild;
        isFirstBuild = false;

        if (result.errors.length > 0) {
          process.stdout.write('\r\x1b[K');
          console.error('✖ esbuild failed:\n');
          for (const err of result.errors) {
            const loc = err.location;
            if (loc) {
              console.error(`  ${loc.file}:${loc.line}:${loc.column}`);
              if (loc.lineText) {
                console.error(`  ${loc.lineText}`);
                console.error(`  ${' '.repeat(loc.column)}^`);
              }
            }
            console.error(`  ${err.text}\n`);
          }
          console.error('Waiting for changes...\n');
          return;
        }

        if (!first) {
          process.stdout.write(`\r\x1b[K\x1b[32m✓ Backend compiled\x1b[0m\n`);
        }

        if (!serverProcess?.channel) {
          serverProcess = forkProcess();
          return;
        }
        serverProcess.send('');
      });
    },
  };
}
